def solve_n_queens(n, fixed):
    """
    Solve N-Queens problem with fixed assignments.
    fixed: dict mapping row -> column
    """
    # Initialize board
    queens = [-1] * n

    # Apply fixed assignments
    for row, col in fixed.items():
        queens[row] = col

    def is_safe(row, col, queens):
        """Check if placing a queen at (row, col) is safe."""
        for r in range(row):
            c = queens[r]
            if c == -1:
                continue
            # Check column
            if c == col:
                return False
            # Check diagonals
            if abs(c - col) == abs(r - row):
                return False
        return True

    def solve(row, queens):
        """Backtracking solver."""
        if row == n:
            return True

        # If this row has a fixed assignment, skip to next
        if queens[row] != -1:
            # Verify the fixed assignment is valid
            if not is_safe(row, queens[row], queens):
                return False
            return solve(row + 1, queens)

        # Try each column
        for col in range(n):
            if is_safe(row, col, queens):
                queens[row] = col
                if solve(row + 1, queens):
                    return True
                queens[row] = -1

        return False

    # First verify fixed assignments don't conflict with each other
    for r1 in range(n):
        if queens[r1] == -1:
            continue
        for r2 in range(r1 + 1, n):
            if queens[r2] == -1:
                continue
            c1, c2 = queens[r1], queens[r2]
            if c1 == c2 or abs(c1 - c2) == abs(r1 - r2):
                print(f"Fixed assignments conflict: row {r1} col {c1} and row {r2} col {c2}")
                return None

    if solve(0, queens):
        return queens
    return None

