from pysat.solvers import Glucose3
from pysat.card import *

def solve_n_queens_sat(n, fixed):
    """
    Solve N-Queens using SAT solver.
    """
    solver = Glucose3()

    # Variable x[r][c] = True means queen at row r, column c
    # Variable index: r * n + c + 1 (1-indexed for SAT)
    def var(r, c):
        return r * n + c + 1

    # Each row must have exactly one queen
    for r in range(n):
        # At least one queen in row r
        solver.add_clause([var(r, c) for c in range(n)])
        # At most one queen in row r
        for c1 in range(n):
            for c2 in range(c1 + 1, n):
                solver.add_clause([-var(r, c1), -var(r, c2)])

    # Each column must have at most one queen
    for c in range(n):
        for r1 in range(n):
            for r2 in range(r1 + 1, n):
                solver.add_clause([-var(r1, c), -var(r2, c)])

    # Diagonal constraints
    # Main diagonals (r - c = constant)
    for diff in range(-(n-1), n):
        cells = [(r, c) for r in range(n) for c in range(n) if r - c == diff]
        for i in range(len(cells)):
            for j in range(i + 1, len(cells)):
                r1, c1 = cells[i]
                r2, c2 = cells[j]
                solver.add_clause([-var(r1, c1), -var(r2, c2)])

    # Anti-diagonals (r + c = constant)
    for s in range(0, 2 * n - 1):
        cells = [(r, c) for r in range(n) for c in range(n) if r + c == s]
        for i in range(len(cells)):
            for j in range(i + 1, len(cells)):
                r1, c1 = cells[i]
                r2, c2 = cells[j]
                solver.add_clause([-var(r1, c1), -var(r2, c2)])

    # Fixed assignments
    for r, c in fixed.items():
        solver.add_clause([var(r, c)])
        # No other queen in this row
        for c2 in range(n):
            if c2 != c:
                solver.add_clause([-var(r, c2)])
        # No other queen in this column
        for r2 in range(n):
            if r2 != r:
                solver.add_clause([-var(r2, c)])

    if solver.solve():
        model = solver.get_model()
        solution = [-1] * n
        for r in range(n):
            for c in range(n):
                if var(r, c) in model:
                    solution[r] = c
                    break
        return solution
    else:
        return None

