def verify_solution(solution, fixed):
    n = len(solution)
    # Check fixed assignments
    for r, c in fixed.items():
        if solution[r] != c:
            print(f"Fixed assignment violated: row {r} should be {c}, got {solution[r]}")
            return False

    # Check all constraints
    for r1 in range(n):
        for r2 in range(r1 + 1, n):
            c1, c2 = solution[r1], solution[r2]
            # Same column
            if c1 == c2:
                print(f"Column conflict: rows {r1},{r2} both have column {c1}")
                return False
            # Same diagonal
            if abs(c1 - c2) == abs(r1 - r2):
                print(f"Diagonal conflict: ({r1},{c1}) and ({r2},{c2})")
                return False

    print("Solution verified successfully!")
    return True

